export function getTranslatedSanyMachineTitle(model: string, language: string = 'en'): string {
  const translations = sanyMachineTranslations[model];
  if (!translations) return model;
  return translations[language] || translations['en'] || model;
}

export function getTranslatedSanyMachineType(type: string, language: string = 'en'): string {
  const translations = sanyMachineTypeTranslations[type];
  if (!translations) return type;
  return translations[language] || translations['en'] || type;
}


