export function getTranslatedSanyMachineSpecs(model: string, language: string = 'en'): string {
  const translations = sanyMachineSpecsTranslations[model];
  if (!translations) return '';
  return translations[language] || translations['en'] || '';
}

export function getTranslatedSanyMachineDescription(description: string, language: string = 'en'): string {
  // Try to find by model from description
  for (const [model, translations] of Object.entries(sanyMachineDescriptionTranslations)) {
    if (description.includes(model)) {
      return translations[language] || translations['en'] || description;
    }
  }
  return description;
}

